 internal static int Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","zoo124-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);DisplayOptions.TestPath=Path.Combine(root,"display-options.json");typeof(DisplayOptions).GetField("current",BindingFlags.NonPublic|BindingFlags.Static)!.SetValue(null,null);var checks=new List<string>();void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
